float trial = integral + Ki * error * dt;
float unsat = base + Kp * error + trial;
bool inside = unsat >= 0 && unsat <= 255;
bool returning = (unsat > 255 && error < 0)
              || (unsat < 0 && error > 0);
if (inside || returning) integral = trial;
float u = constrain(base + Kp*error + integral,
                    0.0f, 255.0f);

